<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {bookApi} from '../../api/ebrBook'
import {useAuthStore} from '../../stores/auth'
import {errorMessage} from '../../api/http'
import PdfPreview from '../../components/printing/PdfPreview.vue'
import {bookStates,mayFormal,type BatchBook,type BookPdf} from './bookModel'
const route=useRoute(),router=useRouter(),auth=useAuthStore(),book=ref<BatchBook|null>(null),selected=ref(''),busy=ref(false),error=ref(''),history=ref<BookPdf[]>([]),blob=ref<Blob|null>(null),pdfOpen=ref(false),reason=ref(''),kind=ref<'REVIEW_COPY'|'FINAL'>('REVIEW_COPY')
const current=computed(()=>book.value?.entries.find(e=>e.definition.code===selected.value)),formalReady=computed(()=>book.value?mayFormal(book.value):false)
let generation=0
async function load(){const ticket=++generation;busy.value=true;error.value='';try{const value=await bookApi.read(String(route.params.id));if(ticket!==generation)return;book.value=value;if(!value.entries.some(e=>e.definition.code===selected.value))selected.value=value.entries[0]?.definition.code??'';history.value=value.legacy?[]:await bookApi.history(value.mainBatchId)}catch(e){if(ticket===generation)error.value=errorMessage(e)}finally{if(ticket===generation)busy.value=false}}
async function openPdf(record:BookPdf){if(!book.value)return;busy.value=true;error.value='';try{blob.value=await bookApi.pdf(book.value.mainBatchId,record);pdfOpen.value=true}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function generate(){if(!book.value)return;if(!reason.value.trim()){error.value='请填写整册生成原因';return}busy.value=true;error.value='';try{const record=await bookApi.generate(book.value,kind.value,reason.value.trim());await openPdf(record);await load()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
watch(()=>route.params.id,()=>{blob.value=null;pdfOpen.value=false;selected.value='';load()},{immediate:true})
</script>
<template><main data-ui-template="T4" class="admin-page master-page book-page"><header class="admin-page-header"><div><h1>生产批记录册</h1><p>按冻结目录查阅原始记录，过程填写与复核沿用现有受控表单。</p></div><a-space wrap><a-button @click="router.push(`/production/batches/${route.params.id}`)">返回生产批</a-button><a-button :loading="busy" @click="load">刷新记录</a-button></a-space></header><a-alert v-if="error" type="error" :message="error" show-icon/><a-skeleton v-if="busy&&!book" active/><template v-if="book"><a-card class="book-summary"><a-descriptions :column="{xs:1,sm:2,md:3}"><a-descriptions-item label="品名">{{book.productName}}</a-descriptions-item><a-descriptions-item label="规格">{{book.specification||'未提供'}}</a-descriptions-item><a-descriptions-item label="批号">{{book.batchNo}}</a-descriptions-item><a-descriptions-item label="批量">{{book.plannedQty}} {{book.unitName}}</a-descriptions-item><a-descriptions-item label="状态">{{({DRAFT:'草稿',IN_PROGRESS:'生产中',COMPLETED:'已完成',QA_RELEASED:'QA已放行',REJECTED:'已拒绝'} as Record<string,string>)[book.status]??book.status}}</a-descriptions-item><a-descriptions-item label="冻结册版本">{{book.book?`V${book.book.templateRevision}`:'原eBR版本'}}</a-descriptions-item></a-descriptions></a-card><section v-if="book.legacy" class="legacy-book"><a-alert type="info" :message="book.status==='DRAFT'?'批次尚未下达，尚未冻结记录册模板。':book.notice" show-icon/><a-card title="记录册未冻结"><p v-if="book.status==='DRAFT'">新册模板需要先由授权人员配置规格适用映射并独立发布，再由原批次下达流程冻结。页面不会替代下达或审核操作。</p><p v-else>此批次保留原冻结 eBR 与归档证据，新册模板不追改已经下达的批次。可以继续查看原电子批记录及其合法填写、复核和归档入口。</p><a-space wrap><a-button @click="router.push({path:`/production/batches/${book.mainBatchId}`,query:{tab:'ebr'}})">查看原电子批记录</a-button><a-button v-if="auth.can('ebr:template:view')&&auth.can('master:product:view')&&auth.can('process:package:view')" @click="router.push('/ebr/book-templates')">查看记录册模板配置</a-button><a-button v-if="auth.can('qa:batch-review')" @click="router.push(`/qa/batches/${book.mainBatchId}/review`)">查看原审核与归档证据</a-button></a-space></a-card></section><div v-else class="book-layout"><aside class="book-directory" aria-label="批记录目录"><h2>批记录目录</h2><button v-for="item in book.entries" :key="item.definition.code" class="directory-item" :class="{active:selected===item.definition.code}" :aria-current="selected===item.definition.code?'page':undefined" @click="selected=item.definition.code"><span class="chapter">{{item.definition.chapter}}</span><strong>{{item.definition.order}}. {{item.definition.title}}</strong><span class="directory-status" :class="item.state">{{bookStates[item.state]??item.state}}</span><small>{{item.documents.length}} 份来源记录{{item.definition.required?' · 必需':''}}</small></button></aside><section class="book-record" aria-label="对应记录表格"><header><h2>{{current?.definition.title}}</h2><p>{{current?.definition.scope==='BATCH'?'整批一份过程记录；明细可多行。':'按冻结目录及实际业务来源呈现。'}}</p></header><a-alert v-if="current&&!current.documents.length" :type="current.state==='MISSING'?'warning':'info'" :message="current.notice??bookStates[current.state]" show-icon/><article v-for="doc in current?.documents" :key="`${doc.sourceType}-${doc.sourceId}`" class="paper-record"><div class="record-heading"><div><h3>{{doc.title}}</h3><span>来源版本 {{doc.sourceVersion||'不可变证据'}} · {{bookStates[doc.status]??doc.status}}</span></div><a-button v-if="doc.url&&doc.sourceType!=='ATTACHMENTS'" :disabled="busy" @click="router.push(doc.url!)">{{doc.formId&&(auth.can('ebr:form:edit')||auth.can('ebr:review:verify')||auth.can('ebr:review:approve'))?'填写 / 复核':'查看原记录'}}</a-button></div><div class="paper-table-scroll"><table><thead><tr><th v-for="col in doc.columns" :key="col">{{col}}</th></tr></thead><tbody><tr v-for="(row,index) in doc.rows" :key="index"><td v-for="(value,cell) in row" :key="cell">{{value||'未记录'}}</td></tr></tbody></table></div><p v-if="doc.signatureIds" class="record-signature">电子签名记录：{{doc.signatureIds.length?doc.signatureIds.join('、'):'未签署'}}。打印不替代原签名验证。</p></article></section></div><a-card v-if="!book.legacy" title="整册预览与归档" class="book-export"><a-space wrap v-if="auth.can('ebr:pdf:generate')"><a-select v-model:value="kind" aria-label="整册类型"><a-select-option value="REVIEW_COPY">审核副本 / 草稿</a-select-option><a-select-option value="FINAL" :disabled="!formalReady">正式归档</a-select-option></a-select><a-input v-model:value="reason" aria-label="生成原因" placeholder="整册生成原因" maxlength="1000"/><a-button type="primary" :loading="busy" @click="generate">生成并预览整册 PDF</a-button></a-space><p>正式归档要求必需项完成及现有 QA 审核条件。来源更正生成新产物，旧版重打读取原归档 PDF。</p><a-table :scroll="{x:650}" row-key="id" :data-source="history" :pagination="false" :columns="[{title:'产物版本',dataIndex:'id'},{title:'类型',dataIndex:'archive_kind'},{title:'时间',dataIndex:'created_at'},{title:'操作',key:'action'}]"><template #bodyCell="{column,record}"><a-button v-if="column.key==='action'" type="link" :disabled="busy" @click="openPdf(record)">预览 / 重打</a-button></template></a-table></a-card></template><a-modal v-model:open="pdfOpen" title="整册PDF · 同一归档产物" :width="'min(1100px,96vw)'" :footer="null"><PdfPreview :blob="blob" :name="`生产批记录册-${book?.batchNo??'批次'}.pdf`"/></a-modal></main></template>
<style scoped>.legacy-book{display:grid;gap:16px}.legacy-book p{color:#65748a;line-height:1.8}.book-page{display:grid;gap:18px;min-width:0;width:100%}.book-page>*{min-width:0}.book-summary :deep(.ant-descriptions-item-content){overflow-wrap:anywhere}.book-export{overflow:hidden}.book-layout{display:grid;grid-template-columns:260px minmax(0,1fr);gap:20px;align-items:start}.book-directory{background:#fff;border:1px solid #dbe2ed;border-radius:8px;padding:18px;position:sticky;top:12px}.book-directory h2,.book-record h2{font-size:17px;margin:0 0 14px}.directory-item{display:flex;flex-direction:column;width:100%;gap:7px;padding:14px;text-align:left;border:1px solid transparent;border-radius:6px;background:transparent;color:#24334b;cursor:pointer;margin-bottom:5px}.directory-item.active{background:#edf4ff;border-color:#b9d2fa}.directory-item:focus-visible{outline:2px solid #2468cc}.chapter,.directory-item small,.record-heading span,.record-signature{font-size:12px;color:#65748a}.directory-status{font-size:12px;color:#9b641a}.directory-status.COMPLETE{color:#258356}.directory-status.ACCESS_DENIED{color:#a82b34}.book-record{min-width:0}.book-record>header p,.book-export p{color:#69788b;font-size:13px}.paper-record{background:#fff;border:1px solid #dbe2ed;padding:26px;margin-top:16px}.record-heading{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:22px}.record-heading h3{font-size:18px;margin:0 0 6px}.paper-table-scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}th,td{border:1px solid #7b8797;padding:10px;white-space:pre-wrap;overflow-wrap:anywhere;min-width:85px}th{background:#f4f6fa;text-align:left}.book-export .ant-input{min-width:220px}@media(max-width:850px){.book-layout{grid-template-columns:1fr}.book-directory{position:static}.paper-record{padding:14px}.record-heading{align-items:flex-start}.book-directory .directory-item{padding:10px}}
</style>
